import org.junit.Test;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.stream.Collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class JacksonJsonTransformerTest {

    private JacksonJsonTransformer jacksonJsonTransformer = new JacksonJsonTransformer();

    @Test
    public void parseHttpExceptionScenarioTest() {
        String json = loadJsonFromFile("/HttpException.json");
        HttpException result = jacksonJsonTransformer.parse(json, HttpException.class);
        assertEquals("HttpException", result.getClass().getSimpleName());
    }

    @Test
    public void parseHttpBadRequestExceptionScenarioTest() {
        String json = loadJsonFromFile("/HttpBadRequestException.json");
        HttpBadRequestException result = jacksonJsonTransformer.parse(json, HttpBadRequestException.class);
        assertEquals("HttpBadRequestException", result.getClass().getSimpleName());
    }

    @Test
    public void parseProjectScenarioTest() {
        String json = loadJsonFromFile("/Project.json");
        Project result = jacksonJsonTransformer.parse(json, Project.class);
        assertEquals("Project", result.getClass().getSimpleName());
    }

    @Test
    public void parseInvalidClassScenarioTest() {
        String json = loadJsonFromFile("/HttpException.json");
        try {
            LanguageTranslations result = jacksonJsonTransformer.parse(json, LanguageTranslations.class);
            fail("Expected an InvalidFormatException to be thrown");
        } catch (InvalidFormatException ex) {
            assertTrue(true);
        }
    }

    @Test
    public void convertTest() {
        Project project = new Project();
        String result = jacksonJsonTransformer.convert(project);
        assertTrue(result.matches("\\{\\s*\\}")); // A simple check that resulting string looks like an empty JSON object.
    }

    private String loadJsonFromFile(String fileName) {
        try (InputStream inputStream = getClass().getResourceAsStream(fileName)) {
            if (inputStream == null) {
                throw new IllegalArgumentException("Cannot find " + fileName);
            }
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                return reader.lines().collect(Collectors.joining("\n"));
            }
        } catch (IOException ex) {
            throw new RuntimeException("Could not load JSON", ex);
        }
    }
}
